import math


def best_average(a: list[int], k: int) -> list[int]:
    n = len(a)
    prefix = [0] * (n + 1)
    for i, value in enumerate(a):
        prefix[i + 1] = prefix[i] + value

    def not_left_turn(i: int, j: int, m: int) -> bool:
        return (j - i) * (prefix[m] - prefix[i]) - (prefix[j] - prefix[i]) * (m - i) <= 0

    def slope_less(i: int, j: int, right: int) -> bool:
        return (prefix[right] - prefix[i]) * (right - j) < (prefix[right] - prefix[j]) * (right - i)

    hull: list[int] = []
    best_sum = 0
    best_len = 1

    for right in range(k, n + 1):
        left = right - k
        while len(hull) >= 2 and not_left_turn(hull[-2], hull[-1], left):
            hull.pop()
        hull.append(left)

        lo = 0
        hi = len(hull) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if slope_less(hull[mid], hull[mid + 1], right):
                lo = mid + 1
            else:
                hi = mid

        start = hull[lo]
        cur_sum = prefix[right] - prefix[start]
        cur_len = right - start
        if cur_sum * best_len > best_sum * cur_len:
            best_sum = cur_sum
            best_len = cur_len

    g = math.gcd(best_sum, best_len)
    return [best_sum // g, best_len // g]
